/**
 * Server-side helper to resolve the active persona mode for the current user.
 *
 * Persona modes partition the sidebar into three mental contexts:
 *  - operate  → daily work (Dashboard, Calendar, Appointments, Clients, Inventory)
 *  - manage   → weekly business ops (Team, Money, Marketing)
 *  - configure → one-time setup (Settings hub)
 *
 * Resolution order:
 *  1. Cookie `inkos_active_mode` (httpOnly, SameSite=Lax, Max-Age 31536000)
 *  2. Default mode for the user's role (see getDefaultModeForRole)
 *
 * Access rules:
 *  - artist + guest_artist → operate only (switcher hidden entirely)
 *  - receptionist          → operate + manage (limited Manage — role-gated items filter)
 *  - admin + owner         → all three
 *
 * Mirrors lib/context/active-studio.ts pattern exactly.
 */

import { cookies } from 'next/headers'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export type AppMode = 'operate' | 'manage' | 'configure'

/**
 * Returns the set of modes accessible to this role.
 * Ordering is always operate → manage → configure.
 */
export function getAllowedModes(role: NavRole): AppMode[] {
  if (role === 'artist' || role === 'guest_artist') {
    return ['operate']
  }
  if (role === 'receptionist') {
    return ['operate', 'manage']
  }
  // admin + owner get all three
  return ['operate', 'manage', 'configure']
}

/**
 * Returns the default mode for a role on first login (or when cookie is absent/invalid).
 *
 * admin/owner default to 'manage' — business-operations is their most common daily use.
 * All other roles default to 'operate'.
 */
export function getDefaultModeForRole(role: NavRole): AppMode {
  if (role === 'admin' || role === 'owner') {
    return 'manage'
  }
  return 'operate'
}

/**
 * Resolves the active mode for a given role.
 * Reads the cookie; validates against allowed modes; falls back to role default.
 *
 * Must be called server-side only (uses next/headers cookies()).
 */
export async function getActiveMode(role: NavRole): Promise<AppMode> {
  const cookieStore = await cookies()
  const cookieValue = cookieStore.get('inkos_active_mode')?.value
  const allowed = getAllowedModes(role)

  if (cookieValue && (allowed as string[]).includes(cookieValue)) {
    return cookieValue as AppMode
  }

  return getDefaultModeForRole(role)
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { cookies } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { getAllowedModes, type AppMode } from '@/lib/context/active-mode'
import type { NavRole } from '@/components/app/sidebar/nav-config'

const APP_MODES = ['operate', 'manage', 'configure'] as const

const SetModeSchema = z.object({
  mode: z.enum(APP_MODES),
})

const COOKIE_NAME = 'inkos_active_mode'
const ONE_YEAR_SECONDS = 31_536_000

export async function POST(request: NextRequest) {
  const supabase = await createClient()
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()

  if (authError || !user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = SetModeSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { mode } = parsed.data

  // Resolve role to validate the requested mode is allowed for this user
  const { data: membership, error: memberError } = await supabase
    .from('studio_members')
    .select('role')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })
    .limit(1)
    .maybeSingle()

  if (memberError) {
    logger.error({ err: memberError, userId: user.id }, 'set-mode: membership lookup failed')
    return NextResponse.json({ error: 'Internal error' }, { status: 500 })
  }

  if (!membership) {
    return NextResponse.json({ error: 'Forbidden — no studio membership found' }, { status: 403 })
  }

  const role = membership.role as NavRole
  const allowed: AppMode[] = getAllowedModes(role)

  if (!allowed.includes(mode)) {
    return NextResponse.json(
      { error: `Forbidden — mode '${mode}' is not allowed for role '${role}'` },
      { status: 403 }
    )
  }

  const isProduction = process.env.NODE_ENV === 'production'
  const cookieStore = await cookies()

  cookieStore.set(COOKIE_NAME, mode, {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
    maxAge: ONE_YEAR_SECONDS,
    secure: isProduction,
  })

  return NextResponse.json({ ok: true })
}

/**
 * Client-side helper to POST a mode switch to /api/context/set-mode.
 *
 * Returns 'ok' on success, 'error' on failure.
 * The caller is responsible for router.refresh() on 'ok' and toast.error() on 'error'.
 *
 * Used by both:
 *  - components/shared/ModeSwitcher.tsx (click handler)
 *  - components/app/sidebar/AppHeader.tsx (G+O/M/E keyboard chord handler)
 *
 * This is a client-only utility — do NOT import in Server Components or API routes.
 */

import type { AppMode } from '@/lib/context/active-mode'

export async function switchMode(mode: AppMode): Promise<'ok' | 'error'> {
  try {
    const res = await fetch('/api/context/set-mode', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mode }),
    })
    if (!res.ok) {
      return 'error'
    }
    return 'ok'
  } catch {
    return 'error'
  }
}

