'use client'

/**
 * ModeSwitcher — Persona mode segmented control
 *
 * Partitions the sidebar into three mental contexts:
 *  - Operate  (CalendarCheck) — daily appointment-first mindset
 *  - Manage   (Briefcase)     — business operations
 *  - Configure (Cog)          — software configuration
 *
 * Variants:
 *  - expanded  → horizontal segmented control, 32px height (default, sidebar expanded)
 *  - collapsed → vertical icon stack, 40×40 buttons (sidebar icon-only mode)
 *  - mobile    → horizontal segmented control, 44px touch height (MobileNav sheet)
 *
 * Returns null when allowedModes.length <= 1 — no DOM, no reserved space.
 *
 * Interaction mirrors StudioSwitcher exactly:
 *  - POST /api/context/set-mode → router.refresh() on success
 *  - toast.error() on failure, pending state while in-flight
 *  - No optimistic update — activeMode only changes after refresh propagates server props
 */

import { useEffect, useRef, useState } from 'react'
import { useRouter } from 'next/navigation'
import { CalendarCheck, Briefcase, Cog, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import { switchMode } from '@/lib/context/switch-mode'
import type { AppMode } from '@/lib/context/active-mode'

export type { AppMode }

export interface ModeSwitcherProps {
  activeMode: AppMode
  allowedModes: AppMode[]
  /** @default 'expanded' */
  variant?: 'expanded' | 'collapsed' | 'mobile'
}

interface ModeConfig {
  mode: AppMode
  label: string
  Icon: typeof CalendarCheck
  ariaLabel: string
}

const MODE_CONFIG: ModeConfig[] = [
  {
    mode: 'operate',
    label: 'Operate',
    Icon: CalendarCheck,
    ariaLabel: 'Switch to Operate mode',
  },
  {
    mode: 'manage',
    label: 'Manage',
    Icon: Briefcase,
    ariaLabel: 'Switch to Manage mode',
  },
  {
    mode: 'configure',
    label: 'Configure',
    Icon: Cog,
    ariaLabel: 'Switch to Configure mode',
  },
]

export function ModeSwitcher({
  activeMode,
  allowedModes,
  variant = 'expanded',
}: ModeSwitcherProps) {
  const router = useRouter()
  const [pending, setPending] = useState<AppMode | null>(null)
  const announcerRef = useRef<HTMLSpanElement | null>(null)

  // Announce successful mode switch to screen readers
  useEffect(() => {
    if (!announcerRef.current) return
    const label = MODE_CONFIG.find((m) => m.mode === activeMode)?.label ?? activeMode
    announcerRef.current.textContent = `Switched to ${label} mode`
  }, [activeMode])

  // Returns null when role has only 1 allowed mode — no DOM, no reserved space
  if (allowedModes.length <= 1) return null

  const visibleModes = MODE_CONFIG.filter((m) => allowedModes.includes(m.mode))
  const isPendingAny = pending !== null

  async function handleSwitch(mode: AppMode) {
    if (mode === activeMode) return
    if (isPendingAny) return

    setPending(mode)
    const result = await switchMode(mode)

    if (result === 'ok') {
      router.refresh()
      // pending cleared by re-render after refresh — set to null for hygiene
      setPending(null)
    } else {
      toast.error("Couldn't switch mode. Try again.")
      setPending(null)
    }
  }

  if (variant === 'collapsed') {
    return (
      <>
        {/* Screen reader announcer */}
